changeSet.sql:
UPDATE push_reminders reminder SET reminder_origin = 'PERSONAL' FROM calendar_event_availability availability JOIN app_user member ON member.id = availability.user_id WHERE availability.event_id = reminder.event_id AND member.keycloak_id = reminder.user_id AND availability.reminder_minutes IS NOT NULL;
UPDATE push_reminders reminder SET reminder_origin = 'EVENT' FROM calendar_event event WHERE event.id = reminder.event_id AND event.reminder_minutes IS NOT NULL AND reminder.reminder_origin <> 'PERSONAL';
UPDATE push_reminders reminder SET reminder_origin = 'PROFILE' FROM notification_profile profile WHERE profile.user_keycloak_id = reminder.user_id AND profile.deleted = FALSE AND reminder.reminder_origin NOT IN ('PERSONAL', 'EVENT');

DROP INDEX IF EXISTS uq_push_reminder_pending_event_user;
DROP INDEX IF EXISTS idx_push_reminders_send_at_sent;
CREATE INDEX idx_push_reminders_status_send_at ON push_reminders (status, send_at);
CREATE UNIQUE INDEX uq_push_reminder_pending_event_user
  ON push_reminders (event_id, user_id) WHERE deleted = FALSE AND status = 'PENDING';

rollback.sql:
ALTER TABLE push_reminders ADD COLUMN sent BOOLEAN NOT NULL DEFAULT FALSE;
UPDATE push_reminders SET sent = (status <> 'PENDING');
CREATE INDEX idx_push_reminders_send_at_sent ON push_reminders (sent, send_at);
